create table public.establishment_units(id uuid primary key default gen_random_uuid(), sort_order int not null default 0, name text not null, created_at timestamptz not null default now());
create table public.establishment_posts(id uuid primary key default gen_random_uuid(), unit_id uuid not null references public.establishment_units(id) on delete cascade, sort_order int not null default 0, title text not null, rank_allocation jsonb not null default '{}'::jsonb, authorized int not null default 1, created_at timestamptz not null default now());
create table public.appointment_requests(id uuid primary key default gen_random_uuid(), officer_id uuid not null references public.officers(id), post_id uuid not null references public.establishment_posts(id), roles public.app_role[] not null default '{}', justification text, status text not null default 'pending' check (status in ('pending','approved','rejected','cancelled')), requested_by uuid not null default auth.uid(), decided_by uuid, decided_at timestamptz, decision_note text, created_at timestamptz not null default now());
alter table public.officers add column if not exists establishment_post_id uuid references public.establishment_posts(id);
grant select on public.establishment_units, public.establishment_posts, public.appointment_requests to authenticated;
grant all on public.establishment_units, public.establishment_posts, public.appointment_requests to service_role;
alter table public.establishment_units enable row level security;
alter table public.establishment_posts enable row level security;
alter table public.appointment_requests enable row level security;
create policy "staff read units" on public.establishment_units for select to authenticated using (true);
create policy "staff read posts" on public.establishment_posts for select to authenticated using (true);
create policy "hr and command read appointments" on public.appointment_requests for select to authenticated using (public.has_any_role(auth.uid(), array['hr_admin','hr_officer','commandant']::public.app_role[]));
create trigger audit_establishment_units after insert or update or delete on public.establishment_units for each row execute function public.audit_trigger();
create trigger audit_establishment_posts after insert or update or delete on public.establishment_posts for each row execute function public.audit_trigger();
create trigger audit_appointment_requests after insert or update or delete on public.appointment_requests for each row execute function public.audit_trigger();

create or replace function public.submit_appointment(_officer uuid, _post uuid, _roles public.app_role[], _justification text)
returns uuid language plpgsql security definer set search_path=public as $$
declare _id uuid;
begin
  if not public.has_any_role(auth.uid(), array['hr_admin','hr_officer']::app_role[]) then raise exception 'Only HR can stage appointments'; end if;
  if 'system_admin' = any(_roles) then raise exception 'System Administrator cannot be granted through appointments'; end if;
  if not exists(select 1 from officers where id=_officer) or not exists(select 1 from establishment_posts where id=_post) then raise exception 'Unknown officer or post'; end if;
  if exists(select 1 from appointment_requests where officer_id=_officer and status='pending') then raise exception 'This officer already has a pending appointment'; end if;
  insert into appointment_requests(officer_id,post_id,roles,justification) values(_officer,_post,coalesce(_roles,'{}'),nullif(trim(_justification),'')) returning id into _id;
  insert into notifications(user_id,title,body,event_key) select ur.user_id,'Appointment awaiting approval','HR staged an appointment for your decision.','appointment:'||_id||':'||ur.user_id from user_roles ur where ur.role='commandant' on conflict do nothing;
  return _id;
end $$;

create or replace function public.decide_appointment(_id uuid, _approve boolean, _note text)
returns void language plpgsql security definer set search_path=public as $$
declare r appointment_requests; o officers; p establishment_posts; filled int;
begin
  if not public.has_any_role(auth.uid(), array['commandant']::app_role[]) then raise exception 'Only the Commandant can decide appointments'; end if;
  select * into r from appointment_requests where id=_id for update;
  if r.id is null or r.status<>'pending' then raise exception 'Appointment is not pending'; end if;
  if r.requested_by = auth.uid() then raise exception 'You cannot approve an appointment you staged'; end if;
  if _approve then
    select * into o from officers where id=r.officer_id for update;
    select * into p from establishment_posts where id=r.post_id;
    select count(*) into filled from officers where establishment_post_id=p.id and id<>o.id;
    if filled >= p.authorized then raise exception 'Post % is already fully filled', p.title; end if;
    if array_length(r.roles,1) > 0 and o.user_id is null then raise exception 'Link this officer to a staff account before granting system roles'; end if;
    update officers set establishment_post_id=p.id, position=p.title where id=o.id;
    if o.user_id is not null then insert into user_roles(user_id,role) select o.user_id, x from unnest(r.roles) x on conflict do nothing; end if;
  end if;
  update appointment_requests set status=case when _approve then 'approved' else 'rejected' end, decided_by=auth.uid(), decided_at=now(), decision_note=nullif(trim(_note),'') where id=_id;
end $$;

create or replace function public.cancel_appointment(_id uuid)
returns void language plpgsql security definer set search_path=public as $$
begin
  if not public.has_any_role(auth.uid(), array['hr_admin','hr_officer']::app_role[]) then raise exception 'Only HR can cancel'; end if;
  update appointment_requests set status='cancelled', decided_by=auth.uid(), decided_at=now() where id=_id and status='pending';
  if not found then raise exception 'Appointment is not pending'; end if;
end $$;
revoke execute on function public.submit_appointment(uuid,uuid,public.app_role[],text), public.decide_appointment(uuid,boolean,text), public.cancel_appointment(uuid) from public, anon;
grant execute on function public.submit_appointment(uuid,uuid,public.app_role[],text), public.decide_appointment(uuid,boolean,text), public.cancel_appointment(uuid) to authenticated;
